// ── Highlighting ───────────────────────────────────────────────────────────

/** Split a query the same way matchesOrderSearch does. */
function queryWords(query: string): string[] {
  const q = query.trim().normalize('NFC').toLowerCase()
  if (!q) return []
  return q.split(/\s+/).filter((w) => /[\p{L}\p{N}]/u.test(w))
}

// A displayed word (letters plus Telugu vowel signs, or digits).
const TOKEN = /[\p{L}\p{M}\p{N}]+/gu

/** Longest text we will light up whole when only the field as a whole matches. */
const MAX_WHOLE_TEXT = 40

/**
 * Where in one piece of on-screen text the query shows up, as [start, end)
 * offsets into `text` — sorted and merged, ready to paint.
 *
 * Mirrors matchesOrderSearch so what is lit is why the order matched:
 *   1. the word typed as-is            "ravi" in "Ravi Kumar", "4821" in "YFF-4821"
 *   2. phone digits across spaces      "98765" in "+91 98765 43210"
 *   3. a word that sounds/translates   "tamata" or "tomato" → the word "టమాటా"
 *   4. the whole (short) text, when only the field together matches
 *      ("green chilli" → "పచ్చిమిర్చి" style dictionary hits)
 * One-letter words light nothing — they match nearly every letter on screen.
 */
export function searchHighlightRanges(text: string, query: string): Array<[number, number]> {
  if (!text || !text.trim()) return []
  const words = queryWords(query).filter((w) => w.length >= 2)
  if (words.length === 0) return []

  const lower = text.toLowerCase()
  // toLowerCase keeps the length for Latin and Telugu; if some rare letter
  // changes it, offsets would drift, so skip the as-typed pass for that text.
  const sameLength = lower.length === text.length
  const ranges: Array<[number, number]> = []
  let tokens: Array<[number, number, string]> | null = null
  const tokenHits = new Map<string, OrderSearchIndex>()

  for (const word of words) {
    let found = false

    if (sameLength) {
      for (let at = lower.indexOf(word); at !== -1; at = lower.indexOf(word, at + word.length)) {
        ranges.push([at, at + word.length])
        found = true
      }
    }
    if (found) continue

    const digits = word.replace(/\D/g, '')
    if (digits.length >= 3 && digits.length === word.length) {
      const pos: number[] = []
      let onlyDigits = ''
      for (let i = 0; i < text.length; i++) {
        if (text[i] >= '0' && text[i] <= '9') { pos.push(i); onlyDigits += text[i] }
      }
      for (let at = onlyDigits.indexOf(digits); at !== -1; at = onlyDigits.indexOf(digits, at + digits.length)) {
        ranges.push([pos[at], pos[at + digits.length - 1] + 1])
        found = true
      }
      continue
    }

    if (!tokens) {
      tokens = []
      for (const m of text.matchAll(TOKEN)) tokens.push([m.index!, m.index! + m[0].length, m[0]])
    }
    for (const [start, end, tok] of tokens) {
      let idx = tokenHits.get(tok)
      if (!idx) { idx = buildOrderSearchIndex([tok], [tok]); tokenHits.set(tok, idx) }
      if (wordMatches(idx, word)) { ranges.push([start, end]); found = true }
    }
    if (found) continue

    const trimmed = text.trim()
    if (trimmed.length <= MAX_WHOLE_TEXT && wordMatches(buildOrderSearchIndex([trimmed], [trimmed]), word)) {
      const start = text.indexOf(trimmed)
      ranges.push([start, start + trimmed.length])
    }
  }

  ranges.sort((a, b) => a[0] - b[0])
  const merged: Array<[number, number]> = []
  for (const r of ranges) {
    const last = merged[merged.length - 1]
    if (last && r[0] <= last[1]) last[1] = Math.max(last[1], r[1])
    else merged.push([r[0], r[1]])
  }
  return merged
}
