'use client'

import { useEffect, useState } from 'react'
import { searchHighlightRanges } from '@/lib/orderSearch'

// Paints the Orders-page search words inside the order list.
//
// Uses the CSS Custom Highlight API (CSS.highlights + ::highlight(order-search)
// in globals.css): the browser colours text ranges without us touching the
// DOM, so React's own rendering of the cards is never disturbed. Browsers
// without it (iOS before 17.2) simply show no highlight — the search itself
// still works.
//
// Which text lights up is decided by searchHighlightRanges (src/lib/orderSearch),
// so a sounds-like or other-language match lights the word it matched.

const HIGHLIGHT_NAME = 'order-search'

// Text the user can't read as order content.
const SKIP_TAGS = new Set(['SCRIPT', 'STYLE', 'INPUT', 'TEXTAREA', 'SELECT', 'OPTION'])

/**
 * Returns a ref callback for the element holding the order list. While
 * `query` has text, every match inside that element is highlighted, and kept
 * up to date as cards re-render (polling, status changes).
 */
export function useSearchHighlight(query: string) {
  const [el, setEl] = useState<HTMLElement | null>(null)

  useEffect(() => {
    if (typeof CSS === 'undefined' || !('highlights' in CSS) || typeof Highlight === 'undefined') return
    const registry = CSS.highlights
    if (!el || !query.trim()) {
      registry.delete(HIGHLIGHT_NAME)
      return
    }

    const paint = () => {
      const highlight = new Highlight()
      const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT, {
        acceptNode: (node) =>
          node.parentElement && SKIP_TAGS.has(node.parentElement.tagName)
            ? NodeFilter.FILTER_REJECT
            : NodeFilter.FILTER_ACCEPT,
      })
      for (let node = walker.nextNode(); node; node = walker.nextNode()) {
        for (const [start, end] of searchHighlightRanges(node.nodeValue ?? '', query)) {
          const range = document.createRange()
          range.setStart(node, start)
          range.setEnd(node, end)
          highlight.add(range)
        }
      }
      registry.set(HIGHLIGHT_NAME, highlight)
    }

    // Cards re-render on polls and actions; repaint once per frame at most.
    let frame = 0
    const observer = new MutationObserver(() => {
      if (frame) return
      frame = requestAnimationFrame(() => { frame = 0; paint() })
    })
    paint()
    observer.observe(el, { childList: true, subtree: true, characterData: true })

    return () => {
      observer.disconnect()
      if (frame) cancelAnimationFrame(frame)
      registry.delete(HIGHLIGHT_NAME)
    }
  }, [el, query])

  return setEl
}

