// One-time: Telugu for every "How we grow" text saved before auto-translation.
//
// Finds rows with English but no Telugu (farmers.story_quote,
// produce_listings.how_we_grow) and asks the deployed app's /api/translate to
// fill each one — the exact code path a save uses, so the same rules apply
// (never overwrites existing Telugu, never writes English into it).
//
// Run AFTER scripts/telugu-how-we-grow-migration.sql, against ONE environment:
//
//   SUPABASE_URL=https://<ref>.supabase.co \
//   SUPABASE_SERVICE_ROLE_KEY=... \
//   BASE_URL=https://<that environment's site> \
//   node scripts/translate-how-we-grow-backfill.mjs
//
// The Supabase project and BASE_URL must be the same environment. Requests are
// spaced out to stay inside Gemini's free-tier rate limit; run it again to pick
// up anything that failed.

import { createClient } from '@supabase/supabase-js'

const { SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, BASE_URL } = process.env
if (!SUPABASE_URL || !SUPABASE_SERVICE_ROLE_KEY || !BASE_URL) {
  console.error('Set SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY and BASE_URL.')
  process.exit(1)
}

const GAP_MS = 7000
const db = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY)
const targets = [
  { kind: 'farmer', table: 'farmers', source: 'story_quote', target: 'story_quote_te' },
  { kind: 'produce', table: 'produce_listings', source: 'how_we_grow', target: 'how_we_grow_te' },
]

let queued = 0
for (const t of targets) {
  const { data, error } = await db.from(t.table).select('id').not(t.source, 'is', null).is(t.target, null)
  if (error) {
    console.error(`${t.table}: ${error.message} (has the migration run?)`)
    continue
  }
  console.log(`${t.table}: ${data.length} to translate`)
  for (const { id } of data) {
    const res = await fetch(`${BASE_URL.replace(/\/$/, '')}/api/translate`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ kind: t.kind, id }),
    }).catch((e) => ({ ok: false, status: String(e) }))
    console.log(`  ${t.kind} ${id} → ${res.status}`)
    if (res.ok) queued++
    await new Promise((r) => setTimeout(r, GAP_MS))
  }
}
console.log(`Queued ${queued}. Wait a minute, then run again — anything still listed failed and will be retried.`)

