  type TranslationStore,
} from '@/lib/autoTranslate'
import { pickTelugu, teluguPatch } from '@/lib/teluguText'

// Telugu "How we grow": background translation that only fills an empty
// column, keeps hand corrections, and never writes English into the Telugu.

const geminiReply = (text: string, status = 200) =>
  vi.fn(async () => new Response(JSON.stringify({ candidates: [{ content: { parts: [{ text }] } }] }), { status }))

function memoryStore(row: { english: string | null; telugu: string | null } | null) {
  const writes: Array<{ id: string; telugu: string; expectedEnglish: string }> = []
  const store: TranslationStore = {
    read: async () => row,
    write: async (id, telugu, expectedEnglish) => { writes.push({ id, telugu, expectedEnglish }) },
  }
  return { store, writes }
}

describe('translateToTelugu', () => {
  it('returns the Telugu Gemini sends back', async () => {
    const fetch = geminiReply('మేము సహజంగా పండిస్తాము.')
    expect(await translateToTelugu('We grow naturally.', { apiKey: 'k', fetch })).toBe('మేము సహజంగా పండిస్తాము.')
    expect(fetch).toHaveBeenCalledOnce()
  })

  it('skips empty text without calling Gemini', async () => {
    const fetch = geminiReply('x')
    expect(await translateToTelugu('   ', { apiKey: 'k', fetch })).toBeNull()
    expect(fetch).not.toHaveBeenCalled()
  })

  it('gives null, never English, when Gemini fails, is rate-limited, throws, or answers in English', async () => {
    expect(await translateToTelugu('Hi there', { apiKey: 'k', fetch: geminiReply('', 429) })).toBeNull()
    expect(await translateToTelugu('Hi there', { apiKey: 'k', fetch: vi.fn(async () => { throw new Error('timeout') }) })).toBeNull()
    expect(await translateToTelugu('Hi there', { apiKey: 'k', fetch: geminiReply('Hi there') })).toBeNull()
  })

  it('gives null with no API key, without calling out', async () => {
    const fetch = geminiReply('తెలుగు')
    const saved = process.env.GEMINI_API_KEY
    delete process.env.GEMINI_API_KEY
    try {
      expect(await translateToTelugu('Hello', { fetch })).toBeNull()
    } finally {
      if (saved !== undefined) process.env.GEMINI_API_KEY = saved
    }
    expect(fetch).not.toHaveBeenCalled()
  })
})

describe('looksLikeTelugu', () => {
  it('accepts Telugu with a few English farming words, rejects English', () => {
    expect(looksLikeTelugu('ప్రతి 7 రోజులకు drip ద్వారా అందిస్తాము')).toBe(true)
    expect(looksLikeTelugu('We grow food naturally')).toBe(false)
    expect(looksLikeTelugu('123')).toBe(false)
  })
})

describe('fillTeluguTranslation', () => {
  it('translates and saves when there is English and no Telugu', async () => {
    const { store, writes } = memoryStore({ english: 'Cow dung only', telugu: null })
    expect(await fillTeluguTranslation(store, 'id1', async () => 'ఆవు పేడ మాత్రమే')).toBe('translated')
    expect(writes).toEqual([{ id: 'id1', telugu: 'ఆవు పేడ మాత్రమే', expectedEnglish: 'Cow dung only' }])
  })

  it('never touches Telugu that is already there (a moderator correction)', async () => {
    const translate = vi.fn(async () => 'new')
    const { store, writes } = memoryStore({ english: 'Cow dung only', telugu: 'సరిచేసిన తెలుగు' })
    expect(await fillTeluguTranslation(store, 'id1', translate)).toBe('already-telugu')
    expect(translate).not.toHaveBeenCalled()
    expect(writes).toEqual([])
  })

  it('skips a row with no English', async () => {
    const translate = vi.fn(async () => 'x')
    expect(await fillTeluguTranslation(memoryStore({ english: '  ', telugu: null }).store, 'id1', translate)).toBe('no-text')
    expect(await fillTeluguTranslation(memoryStore(null).store, 'id1', translate)).toBe('not-found')
    expect(translate).not.toHaveBeenCalled()
  })

  it('writes nothing when translation fails', async () => {
    const { store, writes } = memoryStore({ english: 'Cow dung only', telugu: null })
    expect(await fillTeluguTranslation(store, 'id1', async () => null)).toBe('failed')
    expect(writes).toEqual([])
  })
})

describe('teluguPatch — what a save writes to the Telugu column', () => {
  const base = { oldEnglish: 'Cow dung', newEnglish: 'Cow dung', oldTelugu: 'ఆవు పేడ', newTelugu: 'ఆవు పేడ' }

  it('leaves the column alone when nothing changed', () => {
    expect(teluguPatch(base)).toBeUndefined()
    // Form opened before the translation existed, nothing typed: don't wipe it.
    expect(teluguPatch({ ...base, oldTelugu: '', newTelugu: '' })).toBeUndefined()
  })

  it('keeps a hand correction', () => {
    expect(teluguPatch({ ...base, newTelugu: ' సరిచేసింది ' })).toBe('సరిచేసింది')
    expect(teluguPatch({ ...base, newEnglish: 'Cow dung and neem', newTelugu: 'ఆవు పేడ, వేప' })).toBe('ఆవు పేడ, వేప')
  })

  it('clears it to translate again when the English changed underneath, or the box was emptied', () => {
    expect(teluguPatch({ ...base, newEnglish: 'Cow dung and neem' })).toBeNull()
    expect(teluguPatch({ ...base, newTelugu: '  ' })).toBeNull()
  })
})

describe('pickTelugu', () => {
  it('shows Telugu to a Telugu reader when there is some, English otherwise', () => {
    expect(pickTelugu('te', 'Cow dung', 'ఆవు పేడ')).toBe('ఆవు పేడ')
    expect(pickTelugu('te', 'Cow dung', null)).toBe('Cow dung')
    expect(pickTelugu('te', 'Cow dung', '  ')).toBe('Cow dung')
    expect(pickTelugu('en', 'Cow dung', 'ఆవు పేడ')).toBe('Cow dung')
  })
})

describe('isTranslateKind', () => {
  it('accepts only the two known texts', () => {
    expect(isTranslateKind('farmer')).toBe(true)
    expect(isTranslateKind('produce')).toBe(true)
    expect(isTranslateKind('orders')).toBe(false)
    expect(isTranslateKind('toString')).toBe(false)
  })
})
